#!/usr/bin/env python3
"""
Round 121b (culprits-tiles-more), 1 October 2026. Upload after round120b_tiles.py.

- scripts/largest_banks.py: Wikidata's "504 Gateway Timeout" (it stops any
  question over a minute) no longer fails the refresh: a question that times
  out is asked in smaller pieces, and if Wikidata still cannot answer, the
  last good copy is kept and the reason written to banks/largest.failed.json.
- scripts/aqueduct.py: Global Forest Watch still refuses the farmland water
  stress table; that is now a warning in aqueduct/build.json, tried again
  each Monday, not a failed refresh every day. The projections are built.
- scripts/soy_money.py (new): the soy traders' offices with each trader's
  revenue (Wikidata), and the Forest 500 banks and investors with the
  financing in Forest 500's own download, once it is in forest500/download/.
- forest500/download/README.md (new): where that download goes.

Every file is written whole, and only if it differs.
"""
import base64, pathlib

FILES = {
    'scripts/largest_banks.py': '',
    'scripts/aqueduct.py': '',
    'scripts/soy_money.py': '',
    'forest500/download/README.md': '',
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"  {name}: already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"  {name}: written")


if __name__ == "__main__":
    main()
